68:     void release() API_AVAILABLE(macosx(10.11))
69:     {
70:         if(layer)
71:         {
72:             [layer.device release];
73:             [layer release];
74:         }
75:         if(view)
76:         {
77:             [view release];
78:         }
79:     }
