166: VkResult MetalSurface::present(PresentImage* image) API_AVAILABLE(macosx(10.11))
167: {
168:     @autoreleasepool
169:     {
170:         auto drawable = metalLayer->getNextDrawable();
171:         if(drawable)
172:         {
