182:                               mipmapLevel:0
183:                               withBytes:image->getImageMemory()->getOffsetPointer(0)
184:                               bytesPerRow:image->getImage()->rowPitchBytes(VK_IMAGE_ASPECT_COLOR_BIT, 0)];
185:             [drawable present];
186: 
187:         }
188:     }
189:     return VK_SUCCESS;
